"""Reject malformed reference data; expectations are generated by Godot only."""
import argparse
import copy
from pathlib import Path
import unittest
from unittest import mock
from tools import run_segment_reference as subject

class SegmentReference(unittest.TestCase):
    def fixture(self):
        return {'rows':[{'position':[0,-20+i], 'velocity':[0,60]} for i in range(100)]}
    def test_known_envelope_and_complete_header(self):
        rows=subject.validate_rows(self.fixture())
        self.assertEqual(len(rows),100)
        header=subject.emit_header(rows)
        self.assertIn('std::array<Frame,100>',header)
        self.assertEqual(header.count('    {{'),100)
    def test_unknown_envelope(self):
        data=self.fixture();data['unknown']=True
        with self.assertRaises(ValueError):subject.validate_rows(data)
    def test_missing_extra_or_wrong_frame_list(self):
        for rows in ([],self.fixture()['rows'][:-1],self.fixture()['rows']+[{}],tuple(self.fixture()['rows'])):
            with self.subTest(rows_type=type(rows)),self.assertRaises(ValueError):subject.validate_rows({'rows':rows})
    def test_unknown_missing_or_wrong_row(self):
        for row in ({'position':[0,0]}, {'position':[0,0],'velocity':[0,0],'unknown':0}, 0):
            data=self.fixture();data['rows'][0]=row
            with self.subTest(row=row),self.assertRaises(ValueError):subject.validate_rows(data)
    def test_nonfinite_boolean_text_and_invalid_vector(self):
        for vector in ([],[0],[0,0,0],[True,0],['0',0],[float('nan'),0],[float('inf'),0],[1000001,0],(0,0)):
            data=self.fixture();data['rows'][0]['position']=vector
            with self.subTest(vector=vector),self.assertRaises(ValueError):subject.validate_rows(data)
    def test_unreviewed_engine_rejected_before_output(self):
        args=argparse.Namespace(godot=Path('build/unreviewed.exe'),out=Path('build/must-not-be-created'),write_fixture=False)
        with mock.patch.object(subject.argparse.ArgumentParser,'parse_args',return_value=args),mock.patch.object(subject,'sha',return_value='0'*64):
            with self.assertRaisesRegex(ValueError,'Unreviewed Godot'):subject.main()

if __name__=='__main__':unittest.main()
